#include <vector>
using namespace std;
void insertionSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 1; i < n; i++) {
        int key = arr[i], j = i - 1;
        while (j >= 0 && arr[j] > key) {     // shift larger elements one step right
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;                    // drop key into the gap it opened
    }
}

s2-merge-sort.code:
#include <vector>
using namespace std;
void merge(vector<int>& arr, int low, int mid, int high) {
    vector<int> temp;
    int left = low, right = mid + 1;
    while (left <= mid && right <= high) {   // merge two sorted halves into temp
        if (arr[left] <= arr[right]) temp.push_back(arr[left++]);
        else temp.push_back(arr[right++]);
    }
    while (left <= mid) temp.push_back(arr[left++]);   // copy any leftovers from the left half
    while (right <= high) temp.push_back(arr[right++]); // ...or the right half
    for (int i = low; i <= high; i++) arr[i] = temp[i - low];
}

void mergeSort(vector<int>& arr, int low, int high) {
    if (low >= high) return;                 // zero or one element is already sorted
    int mid = (low + high) / 2;
    mergeSort(arr, low, mid);                // sort the left half
    mergeSort(arr, mid + 1, high);           // sort the right half
    merge(arr, low, mid, high);              // combine both sorted halves
}

s2-quick-sort.code:
#include <algorithm>
#include <vector>
using namespace std;
int partition(vector<int>& arr, int low, int high) {
    int pivot = arr[low], i = low, j = high;
    while (i < j) {
        while (arr[i] <= pivot && i <= high - 1) i++;  // find something > pivot from the left
        while (arr[j] > pivot && j >= low + 1) j--;    // find something <= pivot from the right
        if (i < j) swap(arr[i], arr[j]);
    }
    swap(arr[low], arr[j]);                  // place the pivot at its final sorted position
    return j;
}

void quickSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        int p = partition(arr, low, high);
        quickSort(arr, low, p - 1);          // everything left of the pivot
        quickSort(arr, p + 1, high);         // everything right of the pivot
    }
}

s2-recursive-bubble-sort.code:
#include <algorithm>
#include <vector>
using namespace std;
void recursiveBubbleSort(vector<int>& arr, int n) {
    if (n <= 1) return;                      // base case: nothing left to sort
    for (int j = 0; j < n - 1; j++)
        if (arr[j] > arr[j + 1]) swap(arr[j], arr[j + 1]);  // bubble the max to the end
    recursiveBubbleSort(arr, n - 1);          // recurse on the shorter, still-unsorted prefix
}

