#include <vector>
using namespace std;
void recursiveInsertionSort(vector<int>& arr, int n) {
    if (n <= 1) return;                      // base case: a single element is already sorted
    recursiveInsertionSort(arr, n - 1);      // first, sort everything before arr[n-1]
    int last = arr[n - 1], j = n - 2;
    while (j >= 0 && arr[j] > last) {        // shift larger elements right...
        arr[j + 1] = arr[j];
        j--;
    }
    arr[j + 1] = last;                       // ...then drop last into the gap
}

s2-selection-sort.code:
#include <algorithm>
#include <vector>
using namespace std;
void selectionSort(vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < n; j++)      // find the minimum in the unsorted suffix
            if (arr[j] < arr[minIdx]) minIdx = j;
        swap(arr[i], arr[minIdx]);           // place it at the front of that suffix
    }
}
